(function(){
  var root = document.getElementById('job38-cascade');
  if (!root) return;
  root.innerHTML = "<main>\n    <header>\n      <h1>Job 38: The Question Cascade</h1>\n      <p class=\"subtitle\">A visual rendering of the whirlwind speech as poetic form. The highlights show how repeated questions, repeated knowing-language, and creation-boundary vocabulary turn the speech itself into a storm.</p>\n      <div class=\"legend\" aria-label=\"Highlight legend\">\n        <span class=\"chip\"><span class=\"dot who\"></span> Who? / anaphora</span>\n        <span class=\"chip\"><span class=\"dot or\"></span> Or? / alternation</span>\n        <span class=\"chip\"><span class=\"dot know\"></span> Know / leitwort</span>\n        <span class=\"chip\"><span class=\"dot bound\"></span> Bounds / creation order</span>\n        <span class=\"chip\"><span class=\"dot frame\"></span> Storm frame</span>\n        <span class=\"chip\"><span class=\"dot parallel\"></span> Parallel pairs</span>\n      </div>\n      <p class=\"legend-note\"><strong>How to read the marks:</strong> the colors mark recurring motifs across the whole page. The thin brown underline marks parallel phrases: words or images that answer each other inside the poetic line.</p>\n      <div class=\"hebrew-key\" aria-label=\"Hebrew pattern key\">\n        <div class=\"hebrew-item\"><span class=\"heb\">\u05de\u05b4\u05d9</span><strong><a href=\"https://www.blueletterbible.org/lexicon/h4310/kjv/wlc/0-1/\" target=\"_blank\" data-lexicon=\"who?, whom, whoever\" data-strongs=\"H4310\" data-translit=\"mi\" data-original=\"\u05de\u05b4\u05d9\" data-lang=\"hebrew\" data-verse=\"Job 38:5\">mi</a></strong> = who? The repeated question-word makes the cascade audible.</div>\n        <div class=\"hebrew-item\"><span class=\"heb\">\u05d0\u05d5\u05b9</span><strong><a href=\"https://www.blueletterbible.org/lexicon/h176/kjv/wlc/0-1/\" target=\"_blank\" data-lexicon=\"or, either\" data-strongs=\"H176\" data-translit=\"o\" data-original=\"\u05d0\u05d5\u05b9\" data-lang=\"hebrew\" data-verse=\"Job 38:16\">o</a></strong> = or? Alternating questions pile one realm on another.</div>\n        <div class=\"hebrew-item\"><span class=\"heb\">\u05d9\u05b8\u05d3\u05b7\u05e2</span><strong><a href=\"https://www.blueletterbible.org/lexicon/h3045/kjv/wlc/0-1/\" target=\"_blank\" data-lexicon=\"to know, perceive, understand\" data-strongs=\"H3045\" data-translit=\"yada\" data-original=\"\u05d9\u05b8\u05d3\u05b7\u05e2\" data-lang=\"hebrew\" data-verse=\"Job 38:4\">yada</a></strong> = know. This is the \"know\" thread behind Job 19:25 and Job 38.</div>\n        <div class=\"hebrew-item\"><span class=\"heb\">\u05e9\u05c2\u05d5\u05bc\u05dd</span><strong><a href=\"https://www.blueletterbible.org/lexicon/h7760/kjv/wlc/0-1/\" target=\"_blank\" data-lexicon=\"to put, place, set, appoint\" data-strongs=\"H7760\" data-translit=\"sum\" data-original=\"\u05e9\u05c2\u05d5\u05bc\u05dd\" data-lang=\"hebrew\" data-verse=\"Job 38:5\">sum</a></strong> = set/place/appoint. God sets measures, clouds, bars, and heavenly order.</div>\n        <div class=\"hebrew-item\"><span class=\"heb\">\u05d9\u05b8\u05dd / \u05ea\u05b0\u05bc\u05d4\u05d5\u05b9\u05dd</span><strong><a href=\"https://www.blueletterbible.org/lexicon/h3220/kjv/wlc/0-1/\" target=\"_blank\" data-lexicon=\"sea\" data-strongs=\"H3220\" data-translit=\"yam\" data-original=\"\u05d9\u05b8\u05dd\" data-lang=\"hebrew\" data-verse=\"Job 38:8\">yam</a> / <a href=\"https://www.blueletterbible.org/lexicon/h8415/kjv/wlc/0-1/\" target=\"_blank\" data-lexicon=\"deep, sea, abyss\" data-strongs=\"H8415\" data-translit=\"tehom\" data-original=\"\u05ea\u05b0\u05bc\u05d4\u05d5\u05b9\u05dd\" data-lang=\"hebrew\" data-verse=\"Job 38:16\">tehom</a></strong> = sea / deep. The chaos-symbols are named and bounded.</div>\n        <div class=\"hebrew-item\"><span class=\"heb\">\u05d7\u05b9\u05e7 / \u05d7\u05bb\u05e7\u05bc\u05d5\u05b9\u05ea</span><strong><a href=\"https://www.blueletterbible.org/lexicon/h2706/kjv/wlc/0-1/\" target=\"_blank\" data-lexicon=\"decree, statute, appointed limit\" data-strongs=\"H2706\" data-translit=\"choq\" data-original=\"\u05d7\u05b9\u05e7\" data-lang=\"hebrew\" data-verse=\"Job 38:10\">choq</a> / <a href=\"https://www.blueletterbible.org/lexicon/h2708/kjv/wlc/0-1/\" target=\"_blank\" data-lexicon=\"ordinance, statute\" data-strongs=\"H2708\" data-translit=\"chuqqot\" data-original=\"\u05d7\u05bb\u05e7\u05bc\u05d5\u05b9\u05ea\" data-lang=\"hebrew\" data-verse=\"Job 38:33\">chuqqot</a></strong> = decree / ordinances. Creation has appointed limits.</div>\n      </div>\n    </header>\n\n    <section class=\"overview\" aria-label=\"Pattern counts\">\n      <div class=\"metric\"><strong>13x</strong><span>Hebrew <em>mi</em>, \"who?\", in Job 38</span></div>\n      <div class=\"metric\"><strong>5x</strong><span>Hebrew <em>o</em>, \"or?\", in Job 38</span></div>\n      <div class=\"metric\"><strong>7x</strong><span>Hebrew <em>yada</em>, \"know\", in Job 38</span></div>\n      <div class=\"metric\"><strong>2x</strong><span>Whirlwind frame: Job 38:1 and 40:6</span></div>\n    </section>\n\n    <section class=\"section\">\n      <h2>1. The Storm Frame</h2>\n      <p class=\"section-intro\">The speech begins with the storm. The second divine speech reopens the same frame in Job 40:6.</p>\n      <div class=\"cascade\">\n        <article class=\"verse frame-card\">\n          <div class=\"ref\">38:1</div>\n          <div>\n            <div class=\"text\">Then the Lord answered Job out of the <span class=\"mark frame\">whirlwind</span>, and said,</div>\n            <div class=\"device-note\">Device: doubled frame / theophany. The storm is not only the weather around the answer; it marks the place of revelation.</div>\n          </div>\n        </article>\n        <article class=\"verse frame-card\">\n          <div class=\"ref\">40:6</div>\n          <div>\n            <div class=\"text\">Then answered the Lord unto Job out of the <span class=\"mark frame\">whirlwind</span>, and said,</div>\n            <div class=\"device-note\">Device: repeated frame. The storm returns when the second movement of the divine speech begins.</div>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <h2>2. The Interrogation Opens</h2>\n      <p class=\"section-intro\">Job had wanted a hearing. God answers by becoming the questioner.</p>\n      <div class=\"cascade\">\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:2</div>\n          <div>\n            <div class=\"text\"><span class=\"mark who\">Who</span> is this that <span class=\"mark pa\" data-device=\"Synthetic parallelism. The second phrase explains the first: counsel is darkened by speech that lacks true knowledge.\">darkeneth counsel</span> by <span class=\"mark pa\" data-device=\"Synthetic parallelism. This phrase answers 'darkeneth counsel' by naming the means: words without knowledge.\">words without knowledge</span>?</div>\n            <div class=\"device-note\">Device: opening question. The cascade begins by challenging the limits of human speech.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05de\u05b4\u05d9 ... \u05d3\u05b8\u05e2\u05b7\u05ea</span> The opening \"who?\" is already paired with knowledge-language.</div>\n          </div>\n        </article>\n        <article class=\"verse know-card\">\n          <div class=\"ref\">38:3</div>\n          <div>\n            <div class=\"text\">Gird up now thy loins like a man; for I will <span class=\"mark pa\" data-device=\"Courtroom reversal. God becomes the questioner, reversing Job's request for God to answer him.\">demand</span> of thee, and <span class=\"mark pa\" data-device=\"Courtroom reversal. Job is placed in the respondent's position: God questions, Job must answer.\">answer</span> thou me.</div>\n            <div class=\"device-note\">Device: courtroom reversal. Job asked for God to answer; now God questions Job.</div>\n          </div>\n        </article>\n        <article class=\"verse know-card\">\n          <div class=\"ref\">38:4</div>\n          <div>\n            <div class=\"text\"><span class=\"mark pa\" data-device=\"Question-and-command pair. The first half asks where Job was at creation; the second asks him to prove understanding if he can.\">Where wast thou</span> when I laid the <span class=\"mark bound\">foundations of the earth</span>? <span class=\"mark pa\" data-device=\"Question-and-command pair. 'Declare' answers 'Where wast thou?' by challenging Job to speak from real understanding.\">declare</span>, if thou hast <span class=\"mark know\">understanding</span>.</div>\n            <div class=\"device-note\">Device: creation challenge + knowing-language. The question moves immediately from courtroom to cosmos.</div>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <h2>3. Who? Or? The Questions Begin To Turn</h2>\n      <p class=\"section-intro\">The repeated openings create the effect of wave after wave. This is the core of the question-cascade.</p>\n      <div class=\"cascade\">\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:5</div>\n          <div>\n            <div class=\"text\"><span class=\"mark who\">Who</span> hath <span class=\"mark pa\" data-device=\"Measuring parallelism. 'Laid the measures' and 'stretched the line' belong to the same surveyor/building image: creation is ordered and measured.\">laid the measures</span> thereof, if thou <span class=\"mark know\">knowest</span>? <span class=\"mark or\">or</span> <span class=\"mark who\">who</span> hath <span class=\"mark pa\" data-device=\"Measuring parallelism. This phrase answers 'laid the measures' with a second measuring image: the line stretched across creation.\">stretched the line</span> upon it?</div>\n            <div class=\"device-note\">Device: anaphora + measuring imagery. The earth is pictured as designed, measured, and ordered.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05de\u05b4\u05d9 ... \u05ea\u05b5\u05d3\u05b8\u05e2 ... \u05d0\u05d5\u05b9 \u05de\u05b4\u05d9</span> The Hebrew stacks \"who?\" + \"know?\" + \"or who?\" in one verse.</div>\n          </div>\n        </article>\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:6</div>\n          <div>\n            <div class=\"text\">Whereupon are the <span class=\"mark pa\" data-device=\"Architectural parallelism. Foundations and cornerstone treat the earth as a constructed, ordered building.\">foundations</span> thereof fastened? <span class=\"mark or\">or</span> <span class=\"mark who\">who</span> laid the <span class=\"mark pa\" data-device=\"Architectural parallelism. Cornerstone answers foundations as the second construction image in the pair.\">corner stone</span> thereof;</div>\n            <div class=\"device-note\">Device: synthetic parallelism. The second question presses the first further into construction imagery.</div>\n          </div>\n        </article>\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:8</div>\n          <div>\n            <div class=\"text\"><span class=\"mark or\">Or</span> <span class=\"mark who\">who</span> <span class=\"mark pa\" data-device=\"Boundary-and-birth pairing. The sea is both enclosed by doors and pictured as breaking from a womb: chaos becomes creaturely and bounded.\">shut up the sea with doors</span>, when it <span class=\"mark pa\" data-device=\"Boundary-and-birth pairing. 'Brake forth' and 'issued out of the womb' give the sea birth imagery instead of divine-rival status.\">brake forth, as if it had issued out of the womb</span>?</div>\n            <div class=\"device-note\">Device: chaos bounded. The sea is powerful, but it is enclosed by God.</div>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <h2>4. The Sea Has Doors</h2>\n      <p class=\"section-intro\">The poem moves from storm to sea to boundary. These verses make the chaos-symbol architectural: doors, bars, decrees, and limits.</p>\n      <div class=\"cascade\">\n        <article class=\"verse bound-card\">\n          <div class=\"ref\">38:10</div>\n          <div>\n            <div class=\"text\">And brake up for it my <span class=\"mark bound pa\" data-device=\"Boundary parallelism. The decreed place is the appointed limit; bars and doors make that limit visible as architecture.\">decreed place</span>, and <span class=\"mark bound pa\" data-device=\"Boundary parallelism. Bars and doors answer 'decreed place' by turning divine decree into a physical boundary image.\">set bars and doors</span>,</div>\n            <div class=\"device-note\">Device: semantic field. Decree, bars, and doors all cluster around boundary.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05d7\u05bb\u05e7\u05bc\u05b4\u05d9 ... \u05d0\u05b8\u05e9\u05c2\u05b4\u05d9\u05dd ... \u05d1\u05bc\u05b0\u05e8\u05b4\u05d9\u05d7\u05b7 \u05d5\u05bc\u05d3\u05b0\u05dc\u05b8\u05ea\u05b8\u05d9\u05b4\u05dd</span> Decree + set + bar + doors: the Hebrew makes boundary the controlling image.</div>\n          </div>\n        </article>\n        <article class=\"verse bound-card\">\n          <div class=\"ref\">38:11</div>\n          <div>\n            <div class=\"text\">And said, <span class=\"mark bound pa\" data-device=\"Boundary speech. The spoken limit answers the physical bars and doors: the sea receives an appointed edge.\">Hitherto shalt thou come, but no further</span>: and <span class=\"mark pa\" data-device=\"Boundary speech. The proud waves being stayed restates the limit as restraint.\">here shall thy proud waves be stayed</span>?</div>\n            <div class=\"device-note\">Device: divine limit-speech. God speaks directly to the sea and appoints its edge.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05e2\u05b7\u05d3 \u05e4\u05bc\u05b9\u05d4 ... \u05d5\u05b0\u05dc\u05b9\u05d0 \u05ea\u05b9\u05e1\u05b4\u05d9\u05e3</span> Literally, \"until here ... and no more.\" This spoken boundary answers the physical doors in 38:10.</div>\n          </div>\n        </article>\n      </div>\n      <div class=\"callout\">The Lord does not deny the sea. He doors it. He does not pretend the deep is small. He sets its bounds.</div>\n    </section>\n\n    <section class=\"section\">\n      <h2>5. The Sevenfold Knowing Thread</h2>\n      <p class=\"section-intro\">The repeated knowing-language turns Job 38 into a response to Job 19:25: \"I know that my redeemer liveth.\"</p>\n      <div class=\"cascade\">\n        <article class=\"verse know-card\">\n          <div class=\"ref\">38:12</div>\n          <div>\n            <div class=\"text\">Hast thou <span class=\"mark pa\" data-device=\"Morning/dawn parallelism. Morning and dayspring are paired images; the second half adds that dawn knows its appointed place.\">commanded the morning</span> since thy days; and caused the <span class=\"mark pa\" data-device=\"Morning/dawn parallelism. Dayspring answers morning, then 'know his place' connects light with appointed order.\">dayspring to know his place</span>;</div>\n            <div class=\"device-note\">Device: leitwort. Even dawn knows its appointed place under God's order.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05d9\u05b8\u05d3\u05b7\u05e2\u05b0\u05ea\u05bc\u05b8 \u05e9\u05c1\u05b7\u05d7\u05b7\u05e8 \u05de\u05b0\u05e7\u05b9\u05de\u05d5\u05b9</span> The dawn \"knows\" its place. Knowing is tied to appointed location.</div>\n          </div>\n        </article>\n        <article class=\"verse know-card\">\n          <div class=\"ref\">38:18</div>\n          <div>\n            <div class=\"text\">Hast thou perceived the <span class=\"mark pa\" data-device=\"Intensifying parallelism. Breadth becomes 'all': the second half raises partial perception into comprehensive knowledge.\">breadth of the earth</span>? declare if thou <span class=\"mark know\">knowest</span> it <span class=\"mark pa\" data-device=\"Intensifying parallelism. 'All' intensifies the breadth phrase into a demand for total knowledge.\">all</span>.</div>\n            <div class=\"device-note\">Device: knowing tested. The question exposes the difference between seeing a piece and governing the whole.</div>\n          </div>\n        </article>\n        <article class=\"verse know-card\">\n          <div class=\"ref\">38:21</div>\n          <div>\n            <div class=\"text\"><span class=\"mark know\">Knowest</span> thou it, because thou wast then <span class=\"mark pa\" data-device=\"Ironic alternatives. Being born then and having many days are parallel explanations that both fail to give Job cosmic knowledge.\">born</span>? <span class=\"mark or\">or</span> because the <span class=\"mark pa\" data-device=\"Ironic alternatives. Long life cannot substitute for being present at creation or governing it.\">number of thy days is great</span>?</div>\n            <div class=\"device-note\">Device: irony. Job is asked whether he knows creation because he was there.</div>\n          </div>\n        </article>\n        <article class=\"verse know-card\">\n          <div class=\"ref\">38:33</div>\n          <div>\n            <div class=\"text\"><span class=\"mark know\">Knowest</span> thou the <span class=\"mark bound pa\" data-device=\"Heaven/earth parallelism. The ordinances of heaven are paired with dominion in earth, joining knowledge with governing order.\">ordinances of heaven</span>? canst thou <span class=\"mark bound\">set</span> the dominion thereof in the <span class=\"mark pa\" data-device=\"Heaven/earth parallelism. Earth answers heaven as the lower realm where heavenly order has dominion.\">earth</span>?</div>\n            <div class=\"device-note\">Device: leitwort + boundary language. Knowing and setting belong together; God knows because God governs.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05d4\u05b2\u05d9\u05b8\u05d3\u05b7\u05e2\u05b0\u05ea\u05bc\u05b8 \u05d7\u05bb\u05e7\u05bc\u05d5\u05b9\u05ea \u05e9\u05c1\u05b8\u05de\u05b7\u05d9\u05b4\u05dd ... \u05ea\u05bc\u05b8\u05e9\u05c2\u05b4\u05d9\u05dd</span> Know + ordinances + set: this verse fuses knowledge with appointed cosmic order.</div>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <h2>6. Sea, Deep, Snow, Stars, Storm</h2>\n      <p class=\"section-intro\">The catalogue widens. Job is swept through realms he cannot enter, storehouses he cannot open, and heavens he cannot command.</p>\n      <div class=\"cascade\">\n        <article class=\"verse bound-card\">\n          <div class=\"ref\">38:16</div>\n          <div>\n            <div class=\"text\">Hast thou entered into the springs of the <span class=\"mark bound pa\" data-device=\"Paired realm. Sea and depth name the hidden water-world Job cannot enter but God governs.\">sea</span>? <span class=\"mark or\">or</span> hast thou walked in the search of the <span class=\"mark bound pa\" data-device=\"Paired realm. Depth answers sea as the second hidden-water image in the parallel.\">depth</span>?</div>\n            <div class=\"device-note\">Device: paired realm. Sea and deep name the hidden, threatening, inaccessible world.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05d9\u05b8\u05dd ... \u05ea\u05b0\u05bc\u05d4\u05d5\u05b9\u05dd</span> Sea and deep form the hidden-water pair. This is where the chaos resonance is strongest, while still creaturely.</div>\n          </div>\n        </article>\n        <article class=\"verse or-card\">\n          <div class=\"ref\">38:22</div>\n          <div>\n            <div class=\"text\">Hast thou entered into the <span class=\"mark pa\" data-device=\"Weather-storehouse parallelism. Snow and hail are paired as treasures or storehouses only God can open.\">treasures of the snow</span>? <span class=\"mark or\">or</span> hast thou seen the <span class=\"mark pa\" data-device=\"Weather-storehouse parallelism. Hail answers snow, and the repeated 'treasures' makes the pair explicit.\">treasures of the hail</span>,</div>\n            <div class=\"device-note\">Device: parallel question. Snow and hail become storehouses only God can open.</div>\n          </div>\n        </article>\n        <article class=\"verse or-card\">\n          <div class=\"ref\">38:31</div>\n          <div>\n            <div class=\"text\">Canst thou <span class=\"mark pa\" data-device=\"Antithetic parallelism. Bind and loose are opposite actions in the same cosmic field.\">bind</span> the sweet influences of <span class=\"mark pb\" data-device=\"Constellation pair. Pleiades and Orion mark the paired heavenly realm Job cannot govern.\">Pleiades</span>, <span class=\"mark or\">or</span> <span class=\"mark pa\" data-device=\"Antithetic parallelism. Loose answers bind as its opposite.\">loose</span> the bands of <span class=\"mark pb\" data-device=\"Constellation pair. Orion answers Pleiades as the second constellation in the pair.\">Orion</span>?</div>\n            <div class=\"device-note\">Device: antithetic pair. Bind and loose name opposite powers over the heavens.</div>\n          </div>\n        </article>\n        <article class=\"verse or-card\">\n          <div class=\"ref\">38:34</div>\n          <div>\n            <div class=\"text\">Canst thou lift up thy <span class=\"mark pa\" data-device=\"Command-response parallelism. Job's voice is tested against the storm: can clouds answer his command?\">voice to the clouds</span>, that <span class=\"mark pa\" data-device=\"Command-response parallelism. Abundance of waters is the requested response to the lifted voice.\">abundance of waters may cover thee</span>?</div>\n            <div class=\"device-note\">Device: divine command contrast. Job has a voice, but not a storm-commanding voice.</div>\n          </div>\n        </article>\n        <article class=\"verse or-card\">\n          <div class=\"ref\">38:35</div>\n          <div>\n            <div class=\"text\">Canst thou <span class=\"mark pa\" data-device=\"Command-response parallelism. Sending lightning parallels lifting a voice to clouds: both ask whether the storm obeys Job.\">send lightnings</span>, that they may go, and <span class=\"mark pa\" data-device=\"Personification. Lightning is imagined as a servant that answers its true master, 'Here we are.'\">say unto thee, Here we are</span>?</div>\n            <div class=\"device-note\">Device: personification. Lightning is imagined as a servant answering its master.</div>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <h2>7. The Who Questions Return</h2>\n      <p class=\"section-intro\">Near the end of Job 38, the repeated \"who?\" returns. The speech has circled from foundations and sea to wisdom, clouds, and daily provision.</p>\n      <div class=\"cascade\">\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:25</div>\n          <div>\n            <div class=\"text\"><span class=\"mark who\">Who</span> hath divided a <span class=\"mark pa\" data-device=\"Path parallelism. Watercourse and way both name appointed routes through the storm.\">watercourse</span> for the overflowing of waters, <span class=\"mark or\">or</span> a <span class=\"mark pa\" data-device=\"Path parallelism. The way for lightning answers the watercourse for waters: even storm movement has an appointed path.\">way</span> for the lightning of thunder;</div>\n            <div class=\"device-note\">Device: ordered storm. Even overflowing waters and lightning have a \"way.\"</div>\n          </div>\n        </article>\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:28</div>\n          <div>\n            <div class=\"text\">Hath the <span class=\"mark pb\" data-device=\"Weather-birth parallelism. Rain and dew are treated as generated creatures, not independent powers.\">rain</span> a <span class=\"mark pa\" data-device=\"Birth metaphor. Father-language introduces weather as dependent and generated.\">father</span>? <span class=\"mark or\">or</span> <span class=\"mark who\">who</span> hath <span class=\"mark pa\" data-device=\"Birth metaphor. Begotten answers father: dew is pictured as born under divine providence.\">begotten</span> the drops of <span class=\"mark pb\" data-device=\"Weather-birth parallelism. Dew answers rain as the second weather image in the birth pair.\">dew</span>?</div>\n            <div class=\"device-note\">Device: birth metaphor. Weather is pictured as dependent, generated, and fathered.</div>\n          </div>\n        </article>\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:29</div>\n          <div>\n            <div class=\"text\">Out of <span class=\"mark who\">whose</span> <span class=\"mark pa\" data-device=\"Birth metaphor. Womb-language continues the father/begotten pattern from rain and dew.\">womb</span> came the <span class=\"mark pb\" data-device=\"Weather pair. Ice and hoary frost answer rain and dew as another pair of generated weather-forms.\">ice</span>? and the <span class=\"mark pb\" data-device=\"Weather pair. Hoary frost answers ice as the second cold-weather image.\">hoary frost of heaven</span>, <span class=\"mark who\">who</span> hath <span class=\"mark pa\" data-device=\"Birth metaphor. Gendered continues the birth-language pattern: weather is creaturely and dependent.\">gendered it</span>?</div>\n            <div class=\"device-note\">Device: repeated birth imagery. The hidden origin of weather belongs to God.</div>\n          </div>\n        </article>\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:36</div>\n          <div>\n            <div class=\"text\"><span class=\"mark who\">Who</span> hath put <span class=\"mark pa\" data-device=\"Synonymous parallelism. Wisdom and understanding are a classic Hebrew pair.\">wisdom</span> in the inward parts? <span class=\"mark or\">or</span> <span class=\"mark who\">who</span> hath given <span class=\"mark pa\" data-device=\"Synonymous parallelism. Understanding answers wisdom as the second half of the pair.\">understanding</span> to the heart?</div>\n            <div class=\"device-note\">Device: synonymous parallelism. Wisdom and understanding answer each other.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05de\u05b4\u05d9 ... \u05d7\u05b8\u05db\u05b0\u05de\u05b8\u05d4 \u05d0\u05d5\u05b9 \u05de\u05b4\u05d9 ... \u05d1\u05b4\u05d9\u05e0\u05b8\u05d4</span> The Hebrew repeats the \"who?\" frame around the wisdom/understanding pair.</div>\n          </div>\n        </article>\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:37</div>\n          <div>\n            <div class=\"text\"><span class=\"mark who\">Who</span> can <span class=\"mark pa\" data-device=\"Containment parallelism. Numbering clouds and staying heaven's bottles both picture storm as counted and contained.\">number the clouds</span> in wisdom? <span class=\"mark or\">or</span> <span class=\"mark who\">who</span> can <span class=\"mark pa\" data-device=\"Containment parallelism. Staying the bottles of heaven answers numbering the clouds as another act of storm governance.\">stay the bottles of heaven</span>,</div>\n            <div class=\"device-note\">Device: anaphora + containment. Clouds and heavenly bottles continue the storm-governance motif.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05de\u05b4\u05d9 ... \u05e9\u05c1\u05b0\u05d7\u05b8\u05e7\u05b4\u05d9\u05dd ... \u05de\u05b4\u05d9 ... \u05e0\u05b4\u05d1\u05b0\u05dc\u05b5\u05d9 \u05e9\u05c1\u05b8\u05de\u05b7\u05d9\u05b4\u05dd</span> Two \"who?\" clauses pair clouds with the vessels of heaven.</div>\n          </div>\n        </article>\n        <article class=\"verse who-card\">\n          <div class=\"ref\">38:41</div>\n          <div>\n            <div class=\"text\"><span class=\"mark who\">Who</span> <span class=\"mark pa\" data-device=\"Providence parallelism. Divine provision answers creaturely cry: the speech descends from cosmos to hunger.\">provideth for the raven his food</span>? when his young ones <span class=\"mark pa\" data-device=\"Providence parallelism. The young ones crying to God answer the opening provision question.\">cry unto God</span>, they wander for lack of meat.</div>\n            <div class=\"device-note\">Device: descent from cosmos to creature. The same God who bounds the sea hears the cry of the hungry.</div>\n            <div class=\"hebrew-note\"><span class=\"heb\">\u05de\u05b4\u05d9 ... \u05dc\u05b8\u05e2\u05b9\u05e8\u05b5\u05d1 ... \u05d0\u05b6\u05dc \u05d0\u05b5\u05dc \u05d9\u05b0\u05e9\u05c1\u05b7\u05d5\u05bc\u05b5\u05e2\u05d5\u05bc</span> The \"who?\" question descends to provision: the young cry \"to God.\"</div>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <h2>8. The Shape of the Storm-Cascade</h2>\n      <div class=\"split\">\n        <div class=\"panel\">\n          <h3>What The Form Does</h3>\n          <p>The speech does not climb like a strict staircase. It surrounds like a storm. The repeated questions circle through creation until Job's courtroom demand becomes a vision of God's world.</p>\n        </div>\n        <div class=\"panel\">\n          <h3>What The Doctrine Does</h3>\n          <p>Job does not receive a simple explanation for suffering. He receives a revelation of the God who sets bounds to sea, deep, storm, heaven, and creaturely life.</p>\n        </div>\n      </div>\n      <div class=\"callout\">Job's comfort is not that the storm was imaginary. It is that the storm was not sovereign. The sea had doors. The deep had paths. The whirlwind itself became the place where God spoke.</div>\n      <p class=\"small\" style=\"margin-top:16px;\">Working visual for CFM Corner Week 33. Scripture text is KJV from the local Translation Hub text-access layer. Pattern counts are from the Translation Hub Poetry Analyzer / OSHB tagged Hebrew pass and remain candidates for human review.</p>\n    </section>\n\n    <section class=\"section\">\n      <h2>9. Parallelism Inside the Storm</h2>\n      <p class=\"section-intro\">The cascade is made of two-beat lines. These are conservative examples where the paired phrases are visible even in English. The thin brown underline shows which ideas answer each other across the line.</p>\n\n      <div class=\"parallel-grid\">\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:2</span><span>counsel // knowledge</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark who\">Who</span> is this that <span class=\"mark pa\">darkeneth counsel</span></div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>by <span class=\"mark pa\">words without knowledge</span>?</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Synthetic parallelism:</span> the second beat explains how the counsel is darkened: by speech without knowledge.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05e2\u05b5\u05e6\u05b8\u05d4 ... \u05de\u05b4\u05dc\u05bc\u05b4\u05d9\u05df ... \u05d3\u05b8\u05e2\u05b7\u05ea</span> Counsel, words, and knowledge form the opening problem: speech without true knowing.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:3</span><span>question // answer</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>I will <span class=\"mark pa\">demand</span> of thee,</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>and <span class=\"mark pa\">answer</span> thou me.</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Legal/courtroom parallelism:</span> the speech reverses the courtroom. Job wanted God to answer; God makes Job the respondent.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:4</span><span>where? // declare</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark pa\">Where wast thou</span> when I laid the foundations of the earth?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark pa\">declare</span>, if thou hast <span class=\"mark know\">understanding</span>.</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Question-and-command pair:</span> the first beat asks for Job's location; the second asks him to prove understanding.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:5</span><span>measuring // stretching</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark who\">Who</span> hath laid the <span class=\"mark pa\">measures</span> thereof, if thou <span class=\"mark know\">knowest</span>?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> <span class=\"mark who\">who</span> hath <span class=\"mark pa\">stretched the line</span> upon it?</div>\n          </div>\n          <div class=\"parallel-note\">The second beat restates the first with surveyor imagery. Measures and line belong to one semantic field: ordered creation.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05de\u05b0\u05de\u05b7\u05d3\u05bc\u05b6\u05d9\u05d4\u05b8 ... \u05e7\u05bc\u05b8\u05d5</span> Measures and measuring-line make creation sound planned, surveyed, and set in order.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:6</span><span>foundations // cornerstone</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Whereupon are the <span class=\"mark pa\">foundations</span> thereof fastened?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> <span class=\"mark who\">who</span> laid the <span class=\"mark pa\">corner stone</span> thereof;</div>\n          </div>\n          <div class=\"parallel-note\">The earth is treated like a temple/building. Foundation and cornerstone answer each other as architectural images.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:7</span><span>morning stars // sons of God</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>When the <span class=\"mark pa\">morning stars</span> <span class=\"mark pb\">sang together</span>,</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>and all the <span class=\"mark pa\">sons of God</span> <span class=\"mark pb\">shouted for joy</span>?</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Synonymous parallelism:</span> morning stars answers sons of God; sang together answers shouted for joy.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05db\u05bc\u05d5\u05b9\u05db\u05b0\u05d1\u05b5\u05d9 \u05d1\u05b9\u05e7\u05b6\u05e8 ... \u05d1\u05bc\u05b0\u05e0\u05b5\u05d9 \u05d0\u05b1\u05dc\u05b9\u05d4\u05b4\u05d9\u05dd</span> Morning stars and sons of God are paired in the Hebrew line; singing and shouting answer each other.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:8-9</span><span>birth // clothing</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>the <span class=\"mark pb\">sea</span> ... brake forth, as if it had issued out of the <span class=\"mark pa\">womb</span></div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>when I made the <span class=\"mark pc\">cloud</span> the garment thereof, and thick darkness a <span class=\"mark pc\">swaddlingband</span> for it</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Extended metaphor:</span> the sea is not only bounded; it is born, clothed, and wrapped like an infant. Chaos becomes creaturely.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05d9\u05b8\u05dd ... \u05e8\u05b6\u05d7\u05b6\u05dd ... \u05e2\u05b8\u05e0\u05b8\u05df ... \u05e2\u05b2\u05e8\u05b8\u05e4\u05b6\u05dc</span> Sea, womb, cloud, and thick darkness make the chaos-symbol into a newborn under God's care.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:10-11</span><span>boundary object // boundary speech</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>And brake up for it my <span class=\"mark bound\">decreed place</span>, and <span class=\"mark pa\">set bars and doors</span>,</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>And said, <span class=\"mark bound\">Hitherto shalt thou come, but no further</span>.</div>\n          </div>\n          <div class=\"parallel-note\">The first beat gives the sea physical boundaries; the second gives it spoken boundaries. Door and decree become the same doctrine.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05d7\u05bb\u05e7\u05bc\u05b4\u05d9 ... \u05d0\u05b8\u05e9\u05c2\u05b4\u05d9\u05dd ... \u05e2\u05b7\u05d3 \u05e4\u05bc\u05b9\u05d4</span> The Hebrew moves from decree and setting to \"until here\": boundary as object and boundary as speech.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:12</span><span>morning // dayspring</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Hast thou <span class=\"mark pa\">commanded the morning</span> since thy days;</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>and caused the <span class=\"mark pa\">dayspring</span> to <span class=\"mark know\">know</span> his place;</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Synonymous/building parallelism:</span> morning and dayspring belong together, but the second beat adds appointed place.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05d1\u05bc\u05b9\u05e7\u05b6\u05e8 ... \u05e9\u05c1\u05b7\u05d7\u05b7\u05e8 ... \u05de\u05b0\u05e7\u05b9\u05de\u05d5\u05b9</span> Morning and dawn are paired, then \"his place\" ties the light itself to appointed order.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:16</span><span>sea // depth</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Hast thou entered into the springs of the <span class=\"mark pb\">sea</span>?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> hast thou walked in the search of the <span class=\"mark pb\">depth</span>?</div>\n          </div>\n          <div class=\"parallel-note\">Sea and depth are paired realms. The point is not geography but hiddenness: Job cannot enter what God governs.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05d9\u05b8\u05dd ... \u05ea\u05b0\u05bc\u05d4\u05d5\u05b9\u05dd</span> This pair is important: sea and deep carry the hidden-water/chaos field without making chaos divine.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:18</span><span>breadth // all</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Hast thou perceived the <span class=\"mark pa\">breadth of the earth</span>?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>declare if thou <span class=\"mark know\">knowest</span> it <span class=\"mark pa\">all</span>.</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Intensifying parallelism:</span> breadth becomes all. The second beat raises the demand from perception to comprehensive knowledge.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:21</span><span>birth // many days</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark know\">Knowest</span> thou it, because thou wast then <span class=\"mark pa\">born</span>?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> because the <span class=\"mark pa\">number of thy days is great</span>?</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Irony through parallel alternatives:</span> birth and long life both fail as explanations for cosmic knowledge.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:22</span><span>snow // hail</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Hast thou entered into the <span class=\"mark pc\">treasures of the snow</span>?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> hast thou seen the <span class=\"mark pc\">treasures of the hail</span>,</div>\n          </div>\n          <div class=\"parallel-note\">The repeated \"treasures\" makes the parallel visible. Weather is imagined as storehouses under divine custody.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:25</span><span>watercourse // lightning path</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark who\">Who</span> hath divided a <span class=\"mark pa\">watercourse</span> for the overflowing of waters,</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> a <span class=\"mark pa\">way</span> for the lightning of thunder;</div>\n          </div>\n          <div class=\"parallel-note\">Water and lightning both receive a path. The storm is not random; even overflow has an appointed course.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05ea\u05bc\u05b0\u05e2\u05b8\u05dc\u05b8\u05d4 ... \u05d3\u05bc\u05b6\u05e8\u05b6\u05da\u05b0</span> Watercourse and way/path make storm imagery into ordered movement.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:28-29</span><span>father // womb</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Hath the <span class=\"mark pb\">rain</span> a <span class=\"mark pa\">father</span>? <span class=\"mark or\">or</span> <span class=\"mark who\">who</span> hath begotten the drops of dew?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>Out of <span class=\"mark pa\">whose womb</span> came the <span class=\"mark pb\">ice</span>? and the hoary frost of heaven, <span class=\"mark who\">who</span> hath gendered it?</div>\n          </div>\n          <div class=\"parallel-note\">Weather is cast in birth language. Father, womb, begotten, and gendered turn storm into creaturely dependence.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05d0\u05b8\u05d1 ... \u05de\u05b4\u05d1\u05bc\u05b6\u05d8\u05b6\u05df \u05de\u05b4\u05d9 ... \u05d9\u05b0\u05dc\u05b8\u05d3\u05d5\u05b9</span> Father, womb, and birth verbs make rain, dew, ice, and frost dependent creatures.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:31</span><span>bind // loose</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Canst thou <span class=\"mark pa\">bind</span> the sweet influences of <span class=\"mark pb\">Pleiades</span>,</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> <span class=\"mark pa\">loose</span> the bands of <span class=\"mark pb\">Orion</span>?</div>\n          </div>\n          <div class=\"parallel-note\">This is antithetic parallelism inside the same cosmic field: bind/loose, Pleiades/Orion.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05ea\u05b0\u05e7\u05b7\u05e9\u05c1\u05bc\u05b5\u05e8 ... \u05ea\u05bc\u05b0\u05e4\u05b7\u05ea\u05bc\u05b5\u05d7\u05b7</span> Bind and open/loose form the visible antithesis; Pleiades and Orion mark the paired heavenly realm.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:33</span><span>heaven // earth</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark know\">Knowest</span> thou the <span class=\"mark pc\">ordinances of heaven</span>?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>canst thou <span class=\"mark bound\">set</span> the dominion thereof in the <span class=\"mark pc\">earth</span>?</div>\n          </div>\n          <div class=\"parallel-note\">Heaven and earth form a canonical pair. The verse joins knowing the order with setting its rule.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05d7\u05bb\u05e7\u05bc\u05d5\u05b9\u05ea \u05e9\u05c1\u05b8\u05de\u05b7\u05d9\u05b4\u05dd ... \u05ea\u05bc\u05b8\u05e9\u05c2\u05b4\u05d9\u05dd ... \u05d0\u05b8\u05e8\u05b6\u05e5</span> Ordinances of heaven and rule in earth connect knowledge with the power to set order.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:36</span><span>wisdom // understanding</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark who\">Who</span> hath put <span class=\"mark pa\">wisdom</span> in the inward parts?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> <span class=\"mark who\">who</span> hath given <span class=\"mark pa\">understanding</span> to the heart?</div>\n          </div>\n          <div class=\"parallel-note\">This is one of the clearest fixed-pair examples: wisdom and understanding answer each other directly.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05d7\u05b8\u05db\u05b0\u05de\u05b8\u05d4 ... \u05d1\u05b4\u05d9\u05e0\u05b8\u05d4</span> Wisdom and understanding are a classic Hebrew pair; the repeated <span class=\"heb\">\u05de\u05b4\u05d9</span> frames both halves.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:37</span><span>clouds // bottles of heaven</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark who\">Who</span> can number the <span class=\"mark pb\">clouds</span> in wisdom?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> <span class=\"mark who\">who</span> can stay the <span class=\"mark pb\">bottles of heaven</span>,</div>\n          </div>\n          <div class=\"parallel-note\">Clouds and heavenly bottles keep the storm in view, but now as counted and contained.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05e9\u05c1\u05b0\u05d7\u05b8\u05e7\u05b4\u05d9\u05dd ... \u05e0\u05b4\u05d1\u05b0\u05dc\u05b5\u05d9 \u05e9\u05c1\u05b8\u05de\u05b7\u05d9\u05b4\u05dd</span> Clouds and vessels of heaven turn storm into something numbered, measured, and contained.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:34-35</span><span>voice to clouds // lightning answers</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Canst thou lift up thy <span class=\"mark pa\">voice to the clouds</span>, that abundance of waters may cover thee?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>Canst thou <span class=\"mark pa\">send lightnings</span>, that they may go, and say unto thee, Here we are?</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Command-response parallelism:</span> Job cannot command clouds or lightning. The storm does not answer his voice.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05e7\u05d5\u05b9\u05dc\u05b6\u05da\u05b8 ... \u05d1\u05bc\u05b0\u05e8\u05b8\u05e7\u05b4\u05d9\u05dd ... \u05d4\u05b4\u05e0\u05bc\u05b5\u05e0\u05d5\u05bc</span> Job's voice is contrasted with lightning that can answer \"Here we are\" only to its true Master.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:39-40</span><span>hunt // fill</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span>Wilt thou <span class=\"mark pa\">hunt the prey</span> for the lion?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span><span class=\"mark or\">or</span> <span class=\"mark pa\">fill the appetite</span> of the young lions?</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Synthetic parallelism:</span> hunt names the action; fill the appetite names the need satisfied by that action.</div>\n        </article>\n\n        <article class=\"parallel-card\">\n          <div class=\"parallel-head\"><span>Job 38:41</span><span>provide // cry</span></div>\n          <div class=\"parallel-lines\">\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 1</span><span class=\"mark who\">Who</span> <span class=\"mark pa\">provideth</span> for the raven his food?</div>\n            <div class=\"linebeat\"><span class=\"beat-label\">Beat 2</span>when his young ones <span class=\"mark pa\">cry unto God</span>, they wander for lack of meat.</div>\n          </div>\n          <div class=\"parallel-note\"><span class=\"parallel-type\">Providence parallelism:</span> divine provision answers creaturely cry. The speech descends from cosmos to hunger.</div>\n          <div class=\"hebrew-note\"><span class=\"heb\">\u05de\u05b4\u05d9 \u05d9\u05b8\u05db\u05b4\u05d9\u05df ... \u05d0\u05b6\u05dc \u05d0\u05b5\u05dc \u05d9\u05b0\u05e9\u05c1\u05b7\u05d5\u05bc\u05b5\u05e2\u05d5\u05bc</span> The last \"who?\" of Job 38 lands not on stars or seas, but on God hearing hungry young.</div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <h2>10. Hebrew Texture and Caution Points</h2>\n      <p class=\"section-intro\">These connections are clearer in Hebrew than in English. Click any highlighted term to see the poetic device it is demonstrating.</p>\n\n      <div class=\"connection-grid\">\n        <article class=\"connection-card\">\n          <h3>1. The \"Know\" Duel</h3>\n          <p>Job says, <span class=\"mark know\" data-device=\"Leitwort / repeated root. Job 19:25 uses the Hebrew root yada, 'to know.' Job 38 answers with seven knowing forms, turning Job's confession into a larger question about what kind of knowledge survives the storm.\">\"I know that my redeemer liveth\"</span> in Job 19:25. God answers in Job 38 with a repeated <span class=\"mark know\" data-device=\"Hebrew root-thread. The repeated yada forms make knowledge a counted poetic thread, not just a general topic.\">yada</span> thread.</p>\n          <p class=\"small\">This is not only \"Job lacks information.\" It is a duel over knowing: human confidence, divine knowledge, and the limits of mortal sight.</p>\n        </article>\n\n        <article class=\"connection-card\">\n          <h3>2. The \"Who?\" Storm</h3>\n          <p>The Hebrew <span class=\"mark who\" data-device=\"Anaphora. The same opening word, mi / 'who?', keeps striking the speech like repeated thunder. English sometimes hides this by translating it as 'who' and sometimes as 'whose.'\"><span class=\"heb\">\u05de\u05b4\u05d9</span> / mi / who?</span> appears 13 times in Job 38.</p>\n          <p class=\"small\">The repetition makes the speech sound like a storm-front: who, who, who, each question opening another realm Job cannot govern.</p>\n        </article>\n\n        <article class=\"connection-card\">\n          <h3>3. The Sea as a Newborn</h3>\n          <p>Job 38:8-9 clusters <span class=\"mark pb\" data-device=\"Extended metaphor. The sea is described with birth language: it breaks forth from the womb. Chaos is not treated as divine; it is made creaturely.\">sea breaking forth</span>, <span class=\"mark pa\" data-device=\"Birth imagery. Womb-language turns the sea from a rival chaos power into something born within God's creation.\">womb</span>, <span class=\"mark pc\" data-device=\"Clothing metaphor. God clothes the newborn sea with cloud and wraps it with thick darkness, making chaos bounded and cared for.\">cloud as garment</span>, and <span class=\"mark pc\" data-device=\"Swaddling metaphor. Thick darkness becomes a swaddling band: the sea is powerful, but also infant-like before God.\">thick darkness as swaddling band</span>.</p>\n          <p class=\"small\">The reversal is the point: chaos is not simply defeated; it is born, clothed, and bounded by God.</p>\n        </article>\n\n        <article class=\"connection-card\">\n          <h3>4. Boundary Vocabulary</h3>\n          <p>Job 38:10-11 gathers <span class=\"mark bound\" data-device=\"Semantic field. Decree, bars, doors, and 'no further' all belong to boundary language, making divine order the controlling image.\">decree, bars, doors, and \"no further\"</span>. The Hebrew <span class=\"mark bound\" data-device=\"Repeated root / boundary motif. Sum means set, place, or appoint. Its repetition links creation order to God's act of setting limits.\"><span class=\"heb\">\u05e9\u05c2\u05d5\u05bc\u05dd</span> / sum / set</span> repeats four times in Job 38.</p>\n          <p class=\"small\">God's answer is not \"I am powerful in general.\" It is \"I set limits.\" Sea, deep, storm, and heaven have appointed bounds.</p>\n        </article>\n\n        <article class=\"connection-card\">\n          <h3>5. Ordered Pairs</h3>\n          <p>Hebrew confirms several traditional pairs: <span class=\"mark pc\" data-device=\"Canonical pair. Heaven and earth name the ordered whole: the upper and lower realms under God's rule.\">heaven // earth</span>, <span class=\"mark pa\" data-device=\"Synonymous parallelism. Wisdom and understanding answer each other as a fixed conceptual pair.\">wisdom // understanding</span>, <span class=\"mark pb\" data-device=\"Paired realm. Sea and deep name the hidden water-world, the place of chaos resonance that remains under divine rule.\">sea // deep</span>, and <span class=\"mark pa\" data-device=\"Antithetic parallelism. Bind and loose are opposites within the same cosmic field, showing Job's inability to govern heavenly order.\">bind // loose</span>.</p>\n          <p class=\"small\">These pairings keep the speech ordered even while the cascade feels overwhelming.</p>\n        </article>\n\n        <article class=\"connection-card\">\n          <h3>6. Leviathan Caution</h3>\n          <p>Leviathan should not be flattened into <span class=\"mark frame\" data-device=\"Anachronism caution. Modern categories can distort Job's ancient poetic symbol. Leviathan carries sea-monster and chaos resonance, but it is not a modern dinosaur argument.\">a dinosaur</span>, <span class=\"mark frame\" data-device=\"Anachronism caution. Later theological associations should not erase Job's own poetic use: Leviathan is terrifying to humans but not sovereign before God.\">simply the devil</span>, or <span class=\"mark frame\" data-device=\"Comparative caution. Job may share ancient sea-monster imagery, but Leviathan is not simply Tiamat renamed. Job subordinates the chaos-symbol to Israel's God.\">Tiamat renamed</span>.</p>\n          <p class=\"small\">The safer reading: Leviathan carries ancient chaos resonance, but Job places that terror beneath the rule of God.</p>\n        </article>\n      </div>\n    </section>\n  </main>\n\n  <div class=\"device-modal\" id=\"deviceModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"deviceTitle\" aria-hidden=\"true\">\n    <div class=\"device-dialog\">\n      <div class=\"device-dialog-head\">\n        <p class=\"device-dialog-title\" id=\"deviceTitle\">Poetic Device</p>\n        <button class=\"device-close\" type=\"button\" aria-label=\"Close popup\">x</button>\n      </div>\n      <div class=\"device-dialog-body\">\n        <span class=\"device-term\" id=\"deviceTerm\"></span>\n        <p id=\"deviceText\"></p>\n      </div>\n    </div>\n  </div>";

    const deviceDefaults = {
      who: 'Anaphora / question cascade. Repeated "who?" questions turn the speech into a poetic storm and press Job against the limits of human knowledge.',
      or: 'Alternation. The repeated "or?" keeps adding a second realm, second image, or second challenge so the questions pile up like waves.',
      know: 'Leitwort / repeated root. Knowing-language ties Job 38 back to Job 19:25 and tests the difference between faithful witness and comprehensive divine knowledge.',
      bound: 'Boundary motif. These words belong to decree, measure, door, ordinance, and limit language: God does not merely overpower creation; He appoints its bounds.',
      frame: 'Storm frame / theophany. The whirlwind marks the place of divine address. In Job, the storm is not the final power; it is the place from which God speaks.',
      pa: 'Parallel phrase. This underlined phrase answers another underlined phrase nearby. Read both halves together as one poetic unit.',
      pb: 'Parallel phrase. This underlined phrase answers another underlined phrase nearby. Matching or repeated images make the structure visible.',
      pc: 'Parallel phrase. This underlined phrase answers another underlined phrase nearby. The pair clarifies the device more than either half alone.'
    };

    const modal = document.getElementById('deviceModal');
    const modalTitle = document.getElementById('deviceTitle');
    const modalTerm = document.getElementById('deviceTerm');
    const modalText = document.getElementById('deviceText');
    const closeButton = modal.querySelector('.device-close');
    let lastDeviceTrigger = null;

    function cleanText(text) {
      return text.replace(/\s+/g, ' ').trim();
    }

    function getDeviceClass(mark) {
      return ['who', 'or', 'know', 'bound', 'frame', 'pa', 'pb', 'pc'].find((name) => mark.classList.contains(name));
    }

    function getParallelExplanation(mark) {
      const card = mark.closest('.parallel-card');
      if (!card) return null;
      const head = card.querySelector('.parallel-head');
      const note = card.querySelector('.parallel-note');
      const heading = head ? cleanText(head.innerText) : 'Parallelism';
      const explanation = note ? cleanText(note.innerText) : deviceDefaults[getDeviceClass(mark)];
      return { title: heading, text: explanation };
    }

    function getExplanation(mark) {
      if (mark.dataset.device) {
        return { title: 'Poetic Device', text: mark.dataset.device };
      }

      const parallel = getParallelExplanation(mark);
      if (parallel) return parallel;

      const deviceClass = getDeviceClass(mark);
      return {
        title: 'Poetic Device',
        text: deviceDefaults[deviceClass] || 'This highlight marks a poetic device or Hebrew pattern in the storm-cascade.'
      };
    }

    function openDevice(mark) {
      const explanation = getExplanation(mark);
      lastDeviceTrigger = mark;
      modalTitle.textContent = explanation.title;
      modalTerm.textContent = cleanText(mark.innerText);
      modalText.textContent = explanation.text;
      modal.classList.add('is-open');
      modal.setAttribute('aria-hidden', 'false');
      closeButton.focus();
    }

    function closeDevice() {
      modal.classList.remove('is-open');
      modal.setAttribute('aria-hidden', 'true');
      if (lastDeviceTrigger) lastDeviceTrigger.focus();
    }

    root.querySelectorAll('.mark').forEach((mark) => {
      mark.setAttribute('tabindex', '0');
      mark.setAttribute('role', 'button');
      mark.setAttribute('aria-label', `Explain poetic device: ${cleanText(mark.innerText)}`);
      mark.addEventListener('click', () => openDevice(mark));
      mark.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          openDevice(mark);
        }
      });
    });

    closeButton.addEventListener('click', closeDevice);
    modal.addEventListener('click', (event) => {
      if (event.target === modal) closeDevice();
    });
    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && modal.classList.contains('is-open')) closeDevice();
    });
  
})();
